                    iso_code = iso_code.casefold()
                    iso_codes.setdefault(iso_code, set()).add(code)
                    for name in translated.get(iso_code, []):
                        add_match(native_names, name, code)

            if len(keys) < 1000:
                break
            offset += len(keys)

    def sole_match(codes: set[str] | None, language: str) -> str | None:
        if not codes:
            return None
        if len(codes) != 1:
            raise InvalidLanguage(language)
        return next(iter(codes))

    def iso_to_marc(iso_code: str, language: str) -> str | None:
        assert iso_codes is not None
        if code := sole_match(iso_codes.get(iso_code), language):
            return code

        # Language records without an ISO identifier can still be matched by
        # their English name. This also avoids incorrect entries in the older
        # get_marc21_language fallback map.
        from babel import Locale
        from babel.core import UnknownLocaleError

        try:
            english_name = Locale.parse(iso_code).get_display_name('en')
        except UnknownLocaleError:
            english_name = None

        if english_name:
            if code := sole_match(
                english_names.get(_language_name_key(english_name)), language
            ):
                return code

        code = get_marc21_language(iso_code)
        record = site.get(f'/languages/{code}') if code else None
        if record is None:
            return None
        if english_name and (record_name := record.get('name')):
            expected = _language_name_key(english_name)
            actual = _language_name_key(record_name)
            if actual != expected and not actual.startswith((expected + ',', expected + ' (')):
                return None
        return code

    formatted_languages: list[dict[str, str]] = []
    seen: set[str] = set()
    for language in languages:
        token = language.strip().casefold()
        code = (
            token
            if len(token) == 3 and site.get(f'/languages/{token}') is not None
            else None
        )

        if code is None:
            if iso_codes is None:
                load_language_names()

            name_key = _language_name_key(token)
            is_iso_code = len(token) == 2 and token.isascii() and token.isalpha()
            code = (
                (iso_to_marc(token, token) if is_iso_code else None)
                or sole_match(
                    english_names.get(name_key, set())
                    | native_names.get(name_key, set()),
                    token,
                )
            )
            if code is None and not is_iso_code:
                code = get_marc21_language(token)

            if code is None:
                locale_codes = _locale_language_names().get(name_key)
                if locale_codes:
                    matches = {
                        mapped
                        for iso_code in locale_codes
                        if (mapped := iso_to_marc(iso_code, token))
                        and site.get(f'/languages/{mapped}') is not None
                    }
                    code = sole_match(matches, token)

        if code is None or site.get(f'/languages/{code}') is None:
            raise InvalidLanguage(token)

        if code not in seen:
            formatted_languages.append({'key': f'/languages/{code}'})
            seen.add(code)

    return formatted_languages

